<?php
namespace App\Http\Controllers;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\Rules\Password;class AuthController extends Controller{public function register(Request $r){$d=$r->validate(['name'=>'required|string|max:120','student_no'=>'required|string|max:50|unique:users,student_no','email'=>'required|email|max:180|unique:users,email','password'=>['required','confirmed',Password::min(8)],'role'=>'sometimes|in:student,teacher']);$d['role']=$d['role']??'student';$u=User::create($d);return response()->json(['user'=>$u->load('section'),'token'=>$u->createToken('daylight-web')->plainTextToken],201);}public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string']);$u=User::where('email',$d['email'])->first();if(!$u||!Hash::check($d['password'],$u->password))return response()->json(['message'=>'The provided credentials are incorrect.'],422);return response()->json(['user'=>$u->load('section'),'token'=>$u->createToken('daylight-web')->plainTextToken]);}public function user(Request $r){return $r->user()->load('section');}public function logout(Request $r){$r->user()->currentAccessToken()?->delete();return response()->json(['message'=>'Signed out.']);}public function updateProfile(Request $r){$d=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|unique:users,email,'.$r->user()->id]);$r->user()->update($d);return $r->user()->fresh()->load('section');}}
